mutations.find:
function subtractSpans(spans, holes) {
  const merged = mergeSpans(holes);
  const out = [];
  for (const [from, to] of spans) {
    let lo = 0;
    let hi = merged.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (merged[mid][1] <= from) lo = mid + 1;
      else hi = mid;
    }
    let cursor = from;
    for (let i = lo; i < merged.length && merged[i][0] < to; i += 1) {
      if (merged[i][0] > cursor) out.push([cursor, merged[i][0]]);
      cursor = merged[i][1];
    }
    if (cursor < to) out.push([cursor, to]);
  }
  return out;
}

mutations.replace:
function subtractSpans(spans, holes) {
  let out = spans.map(([from, to]) => [from, to]);
  for (const [holeFrom, holeTo] of holes) {
    const next = [];
    for (const [from, to] of out) {
      if (holeTo <= from || holeFrom >= to) {
        next.push([from, to]);
        continue;
      }
      if (holeFrom > from) next.push([from, holeFrom]);
      if (holeTo < to) next.push([holeTo, to]);
    }
    out = next;
  }
  return out;
}
